import { ViewDepositDetails } from '@/Components/Feature/Backend/ViewDepositDetails';
import StatusBadge from '@/Components/UI/StatusBadge';
import { useTranslations } from '@/Hooks/useTranslations';
import type { CrudConfig, CrudPageProps } from '@/Types/crud';
import { Coins } from 'lucide-react';

export function useDepositConfig(props: CrudPageProps): CrudConfig {
    const { t } = useTranslations();

    const modelProperty = props?.modelProperty;
    const routePrefix = modelProperty?.routePrefix;
    const advanceFilterOptions = props?.advanceFilterOptions || [];

    const baseBreadcrumbs = [
        { label: t('Dashboard'), href: route('backend.dashboard') },
        { label: t('Deposits'), href: route(`${routePrefix}.index`) },
    ];

    return {
        resource: 'deposit',
        resourcePlural: 'deposits',

        title: t('Deposits'),
        description: t('Manage deposit requests'),


        viewDisplayMode: 'modal',
        viewDialogConfig: {
            size: 'xl',
            title: t('View Deposit'),
            description: t('View deposit informatio and action'),
            viewComponent: ViewDepositDetails,
        },

        routes: {
            show: `${routePrefix}.show`,
            index: `${routePrefix}.index`,
            destroy: `${routePrefix}.delete`,
        },

        breadcrumbs: {
            index: [
                { label: t('Dashboard'), href: route('backend.dashboard') },
                { label: t('Deposits'), href: null, active: true },
            ],

        },

        table: {
            serializable: true,
            searchable: true,
            sortable: false,
            selectable: false,

            columns: [
                {
                    key: 'user',
                    label: t('User'),
                    render: (row: any) => (
                        <div>
                            <p className="font-medium">{row?.user?.name}</p>
                            <p className="text-xs text-gray-500">{row?.user?.email}</p>
                        </div>
                    ),
                },

                {
                    key: 'crypto',
                    label: t('Crypto'),
                    // render: (row: any) => row?.crypto?.name || '-',
                    render: (row: any) => (

                        <div className="flex items-center gap-3 max-w-full">
                            {/* Avatar */}
                            <div className="flex-shrink-0 w-10 h-10">
                                {row.crypto?.images?.small ? (
                                    <img
                                        src={row.crypto?.images?.small}
                                        alt={row.crypto?.name}
                                        className="w-10 h-10 object-cover rounded-full border"
                                    />
                                ) : (
                                    <div className="flex items-center justify-center w-10 h-10 rounded-full border bg-gray-100 dark:bg-gray-700">
                                        <Coins className="w-5 h-5 text-gray-400" />
                                    </div>
                                )}
                            </div>

                            {/* Text */}
                            <div className="flex-1 min-w-0">
                                <p
                                    className="text-sm font-medium text-gray-900 dark:text-gray-100
                          truncate leading-tight"
                                    title={row.crypto?.name}
                                >
                                    {row.crypto?.name}
                                </p>
                            </div>
                        </div>
                    )
                },
                {
                    key: 'network',
                    label: t('Network'),
                    render: (row: any) => (
                        <div className="text-sm text-gray-900 dark:text-gray-100">{row.network}</div>
                    )
                },

                {
                    key: 'Deposit Info',
                    label: t('Deposit Info'),
                    render: (row: any) => (
                        <div className="flex flex-col gap-1 text-sm">

                            <div className="flex items-center justify-between gap-4">
                                <span className="text-gray-400">{t('Amount')}</span>
                                <div className="flex items-center gap-1.5">
                                    <Coins className="w-4 h-4 text-green-600" />
                                    <span>{row.amount}</span>
                                </div>
                            </div>

                            <div className="flex items-center justify-between gap-4">
                                <span className="text-gray-400">{t('Fee')}</span>
                                <span>{row.fee_pct} %</span>
                            </div>

                            <div className="flex items-center justify-between gap-4">
                                <span className="text-gray-400">{t('Fee Charged')}</span>
                                <div className="flex items-center gap-1.5">
                                    <Coins className="w-4 h-4 text-green-600" />
                                    <span>{row.fee_charged}</span>
                                </div>
                            </div>

                            <div className="flex items-center justify-between gap-4">
                                <span className="text-gray-400">{t('Final Amount')}</span>
                                <div className="flex items-center gap-1.5 font-medium">
                                    <Coins className="w-4 h-4 text-green-600" />
                                    <span>{row.amount_credited}</span>
                                </div>
                            </div>

                        </div>
                    )

                },

                {
                    key: 'usd_amount',
                    label: t('USD'),
                    render: (row: any) => `$${row.usd_amount}`,
                },

                {
                    key: 'status',
                    label: t('Status'),
                    render: (row: any) => <StatusBadge status={row.status} />,
                },

                {
                    key: 'created_at',
                    label: t('Created At'),
                    sortable: false,
                    renderType: 'date',
                },
            ],
        },

        filters: {
            searchFields: ['username', 'email', 'phone', 'name'],
            filterFields: advanceFilterOptions,
        },

        permissions: {
            actions: {
                view: 'deposit.view',
                edit: 'deposit.edit',
                delete: 'deposit.delete',
            },
        }
    };
}